function previousPromptContext(r,message=''){
 const p=plan(r);const ids=new Set(p.items.flatMap(x=>x.sources.map(s=>s.id)));
 // Topic matching selects trusted texts; message text is never inserted into instructions.
 const topic=norm(message);
 const countryTopics=[[/suisse|switzerland/,['ch-customs','ch-trade']],[/royaume.uni|united kingdom|britain|london|londres/,['uk-export','uk-aml']],[/etats.unis|united states|new york/,['us-import']],[/hong kong/,['hk-customs','hk-declaration']],[/italie|italy/,['it-export']],[/allemagne|germany/,['de-export']],[/canada/,['ca-export']],[/japon|japan/,['jp-export']],[/australie|australia/,['au-export']]];
 for(const [pattern,refs] of countryTopics)if(pattern.test(topic))refs.forEach(id=>ids.add(id));
 if(/deontolog|ethic|cinoa|provenance/.test(topic))ids.add('cinoa-ethics');
 if(/encher|auction/.test(topic)&&norm(r.lieu)==='france')ids.add('fr-auction-ethics');
 if(/inde|india/.test(topic))['india-export','eu-import','eu-thresholds','monaco-customs'].forEach(id=>ids.add(id));
 if(/import|export|douan|custom|transport/.test(topic))['eu-import','eu-thresholds','fr-export','monaco-customs','eu-customs-procedures'].forEach(id=>ids.add(id));
 if(/artiste|artist|deces|death|droit|copyright|70/.test(topic))['fr-copyright','fr-rights','fr-resale','mc-resale'].forEach(id=>ids.add(id));
 if(/vente|sell|sale|contrat|contract|facture|invoice/.test(topic))['fr-attribution','fr-sale','fr-vat','fr-vat-margin','fr-consumer','fr-registry'].forEach(id=>ids.add(id));
 if(/ivoire|ivory|cites|coral|ecaille/.test(topic))ids.add('cites');
 if(/irak|iraq|syrie|syria/.test(topic))ids.add('restricted-origin');
 const selected=SOURCES.filter(s=>ids.has(s.id));
 const ageDays=Math.floor((Date.now()-Date.parse(REVIEWED+'T00:00:00Z'))/86400000);
 return {version:'guide-4.1',reviewed:REVIEWED,coverage:p.coverage,freshness:ageDays>30?'revalidation-required':'within-editorial-review-window',policy:'Sources préchargées et sélectionnées sans recherche réseau. Ni qualification définitive ni vérification de sanctions en temps réel. Si revalidation-required, ne pas présenter les textes comme fraîchement vérifiés. Le code professionnel ne devient pas une loi universelle. Aucun pays non couvert ne reçoit une autorisation par défaut.',sources:selected,nextDocuments:documentsFor(r)};
}

