register('eu-icg-law','UE · règlement 2019/880 : art. 1 à 5, 16 et annexe','https://eur-lex.europa.eu/eli/reg/2019/880/oj/eng',['EU-CUSTOMS'],['import'],'to','Séparer interdiction d’introduction illicite et formalités ICG. Partie B : catégories archéologiques et éléments de monuments, plus de 250 ans ; partie C : catégories désignées, plus de 200 ans ET au moins 18 000 € par objet. Examiner lieu de création/découverte, sortie licite, régime et exceptions ; une absence de formalité ne vaut pas licéité.',{kind:'legislation',legalStatus:'enacted-text',usableFrom:'2025-06-28',pinpoint:'Art. 1–5, 16 ; annexe B/C',versionLabel:'Règles ICG opérationnelles depuis le 28 juin 2025 ; qualification de catégorie requise'});
register('eu-amlr-future','UE · règlement 2024/1624 : calendrier d’application','https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX%3A32024R1624',['EU'],['aml'],'business','L’entrée en vigueur du règlement ne doit pas être confondue avec son application générale le 10 juillet 2027. Les catégories particulières de l’article 3(3)(n)/(o) ont un autre calendrier. Ne pas remplacer prématurément les règles nationales applicables.',{kind:'legislation',legalStatus:'enacted-not-yet-applicable',usableFrom:'2027-07-10',pinpoint:'Article 90',versionLabel:'Calendrier uniquement ; obligations substantielles à qualifier avant activation'});
register('es-export-law','Espagne · Ley 16/1985, articles 5 et 29 à 33','https://www.boe.es/buscar/act.php?id=BOE-A-1985-12534&p=20260527&tn=1',['ES'],['export'],'from','Pour les biens du patrimoine espagnol, examiner l’autorisation préalable, l’Inventario General et les interdictions des biens protégés. Les sorties temporaires et les biens importés documentés ont des règles propres. Une demande avec valeur déclarée peut avoir des conséquences d’offre de vente à l’État : qualifier avant dépôt.',{kind:'legislation',legalStatus:'consolidated-reference',versionLabel:'Consolidation informative BOE, mise à jour publiée le 27 mai 2026',pinpoint:'Art. 5, 29–33 ; original officiel à rapprocher',authority:'Ministerio de Cultura / autorité compétente'});
register('be-export','Belgique · compétence export des biens à Bruxelles','https://economie.fgov.be/fr/themes/politique-commerciale/licences/exportation-de-biens-culturels',['BE'],['export'],'from','Identifier la région où se trouve le bien. Depuis le 11 décembre 2025, le SPF Économie traite les demandes de licence européenne des biens situés à Bruxelles-Capitale. Ne pas choisir la communauté sur la seule langue de l’utilisateur ; les protections patrimoniales restent distinctes.',{pinpoint:'Avis de changement de compétence du 11 décembre 2025',authority:'SPF Économie / communauté compétente selon localisation'});
